1	import { test } from 'node:test';
2	import assert from 'node:assert/strict';
3	import { MultiSession } from '../../src/explore/multi/session.ts';
4	import type { Transport } from '../../src/explore/multi/client.ts';
5	
6	class Fake implements Transport {
7	  sent: any[] = []; closed = false;
8	  onMessage: (m: any) => void = () => {}; onClose: () => void = () => {};
9	  send(m: any) { this.sent.push(m); }
10	  close() { this.closed = true; }
11	}
12	const fl = (...slots: number[]) => slots.map(s => ({ slot: s, name: 'P' + s }));
13	async function make(pick = (n: number) => 0) {
14	  const t = new Fake();
15	  const s = new MultiSession(() => Promise.resolve(t), pick);
16	  let changes = 0; s.onChange = () => { changes++; };
17	  s.open();
18	  await Promise.resolve(); await Promise.resolve();
19	  return { t, s, changes: () => changes };
20	}
21	const lobby = (t: Fake, ...slots: number[]) => t.onMessage({ t: 'lobby', flyers: fl(...slots) });
22	
23	test('kết nối lỗi: phase solo, notice offline', async () => {
24	  const s = new MultiSession(() => Promise.reject(new Error('x')));
25	  s.open(); assert.equal(s.phase, 'connecting');
26	  await new Promise(r => setTimeout(r, 0));
27	  assert.equal(s.phase, 'solo'); assert.equal(s.notice, 'offline');
28	});
29	
30	test('lobby đầu có 5 flyers: watching, watched thuộc 5 slot đó', async () => {
31	  const { t, s } = await make(n => n - 1);
32	  lobby(t, 0, 1, 2, 3, 4);
33	  assert.equal(s.phase, 'watching'); assert.equal(s.watched, 4); assert.equal(s.invite, false);
34	});
35	
36	test('lobby đầu < 5: phase lobby', async () => {
37	  const { t, s } = await make(); lobby(t, 1, 2);
38	  assert.equal(s.phase, 'lobby'); assert.equal(s.flyers.length, 2);
39	});
40	
41	test('join → joined: flying, mySlot đúng', async () => {
42	  const { t, s } = await make(); lobby(t, 1);
43	  s.join('An'); assert.deepEqual(t.sent.at(-1), { t: 'join', name: 'An' }); assert.equal(s.name, 'An');
44	  t.onMessage({ t: 'joined', slot: 3 });
45	  assert.equal(s.phase, 'flying'); assert.equal(s.mySlot, 3);
46	});
47	
48	test('rejected full ở lobby: watching, giữ name', async () => {
49	  const { t, s } = await make(); lobby(t, 0, 1, 2, 3);
50	  s.join('An'); lobby(t, 0, 1, 2, 3, 4); t.onMessage({ t: 'rejected', why: 'full' });
51	  assert.equal(s.phase, 'watching'); assert.equal(s.name, 'An');
52	});
53	
54	test('rejected name: phase giữ nguyên, notice nameBad', async () => {
55	  const { t, s } = await make(); lobby(t);
56	  s.join('x'); t.onMessage({ t: 'rejected', why: 'name' });
57	  assert.equal(s.phase, 'lobby'); assert.equal(s.notice, 'nameBad');
58	});
59	
60	test('watching, flyers < 5: invite true; join rồi rejected full: notice late', async () => {
61	  const { t, s } = await make(); lobby(t, 0, 1, 2, 3, 4);
62	  lobby(t, 0, 1, 2, 3); assert.equal(s.invite, true);
63	  s.join('An'); t.onMessage({ t: 'rejected', why: 'full' });
64	  assert.equal(s.notice, 'late'); assert.equal(s.phase, 'watching');
65	});
66	
67	test('người đang xem rời đi: watched đổi; không còn ai: -1, invite true', async () => {
68	  const { t, s } = await make(); lobby(t, 0, 1, 2, 3, 4);
69	  assert.equal(s.watched, 0);
70	  lobby(t, 1, 2, 3, 4); assert.notEqual(s.watched, 0); assert.ok([1, 2, 3, 4].includes(s.watched));
71	  lobby(t); assert.equal(s.watched, -1); assert.equal(s.invite, true);
72	});
73	
74	test('flyers đổi nhưng người đang xem còn: watched không đổi', async () => {
75	  const { t, s } = await make(n => n - 1); lobby(t, 0, 1, 2, 3, 4);
76	  assert.equal(s.watched, 4); lobby(t, 1, 4); assert.equal(s.watched, 4);
77	});
78	
79	test('đóng kết nối khi flying: solo, lost, flyers rỗng, mySlot -1', async () => {
80	  const { t, s } = await make(); lobby(t, 1); s.join('An'); t.onMessage({ t: 'joined', slot: 2 });
81	  t.onClose();
82	  assert.equal(s.phase, 'solo'); assert.equal(s.notice, 'lost'); assert.equal(s.flyers.length, 0); assert.equal(s.mySlot, -1);
83	});
84	
85	test('đóng kết nối khi watching: notice lost, phase solo', async () => {
86	  const { t, s } = await make(); lobby(t, 0, 1, 2, 3, 4); t.onClose();
87	  assert.equal(s.phase, 'solo'); assert.equal(s.notice, 'lost');
88	});
89	
90	test('released khi flying: watching, notice released', async () => {
91	  const { t, s } = await make(); lobby(t, 1); s.join('An'); t.onMessage({ t: 'joined', slot: 2 });
92	  t.onMessage({ t: 'released' });
