1	/* ===== Dù lượn nhiều người: định dạng tin khách ⇄ máy chủ (JSON) ===== */
2	import { multiParams } from './params';
3	
4	export type ClientMsg =
5	  | { t: 'join'; name: string; kind?: 'walk' }   // kind: 'walk' = xin chỗ đi dạo; không có = chỗ bay (khách cũ)
6	  | { t: 'pos'; x: number; y: number; z: number; yaw: number; bank: number; ts?: number }   // ts: giờ gửi theo đồng hồ của khách (ms); máy chủ cũ bỏ qua
7	  | { t: 'pos'; x: number; y: number; z: number; yaw: number; pose: number; ts?: number }   // người đi dạo: pose (0 đứng, 1 đi, 2 chạy, 3 nhảy, 4 chụp ảnh), không có bank
8	  | { t: 'hb' }
9	  | { t: 'leave' };
10	
11	export interface Flyer { slot: number; name: string }
12	
13	export type Kind = 'fly' | 'walk';
14	
15	// f: mỗi phần tử [slot, x, y, z, yaw, bank, giờ gửi (ms)]; chỉ gồm slot có vị trí mới. Giờ gửi = ts của khách, khách cũ không gửi ts thì là giờ máy chủ nhận;
16	// mỗi slot một trục giờ riêng, khách nhận tự quy đổi. Máy chủ cũ (trước bản sửa giật) gửi 6 phần tử và phát lại vị trí cũ của mọi slot: khách mới nhận được cả hai dạng.
17	// Đi dạo: lobby thêm walkers (flyers chỉ có người bay), pos thêm w (mỗi phần tử [slot, x, y, z, yaw, pose, giờ gửi]; f luôn có, có thể rỗng); khách cũ bỏ qua trường lạ
18	export type ServerMsg =
19	  | { t: 'lobby'; flyers: Flyer[]; walkers?: Flyer[] }
20	  | { t: 'joined'; slot: number; kind?: 'walk' }
21	  | { t: 'rejected'; why: 'full' | 'name'; kind?: 'walk' }
22	  | { t: 'pos'; f: number[][]; w?: number[][] }
23	  | { t: 'released' };
24	
25	// Ký tự trông như khoảng trống dù thuộc nhóm chữ/ký hiệu (chữ đệm Hangul, chữ nổi trống, nguyên âm ẩn Khmer): không tính là chữ thấy được
26	const BLANK = /[\u115F\u1160\u3164\uFFA0\u2800\u17B4\u17B5]/gu;
27	const VISIBLE = /[\p{L}\p{N}\p{S}\p{P}]/u;
28	
29	/* Bỏ ký tự điều khiển và bidi/định dạng (giữ U+200D để ghép emoji), cắt khoảng trắng.
30	   null nếu: rỗng; không có chữ/số/ký hiệu/dấu câu nào thấy được; quá nameMax grapheme; một grapheme quá graphemeCpMax code point (chồng dấu); tổng quá nameCpMax code point */
31	export function exSanitizeName(raw: string): string | null {
32	  if (typeof raw !== 'string') return null;
33	  const s = raw.replace(/[\p{Cc}\p{Cf}]/gu, c => (c === '\u200D' ? c : '')).trim();
34	  if (!s || !VISIBLE.test(s.replace(BLANK, ''))) return null;
35	  const seg = new Intl.Segmenter(undefined, { granularity: 'grapheme' });
36	  let n = 0, cps = 0;
37	  for (const g of seg.segment(s)) {
38	    let k = 0;
39	    for (const _ of g.segment) k++;
40	    cps += k;
41	    if (++n > multiParams.nameMax || k > multiParams.graphemeCpMax || cps > multiParams.nameCpMax) return null;
42	  }
43	  return s;
44	}
