1	/* ===== Dù lượn nhiều người: giao diện chế độ xem và các thông báo =====
2	   #exMpWatch "Đang xem: tên", #exMpInvite (lời mời khi còn chỗ: ô tên nếu chưa có tên hợp lệ + nút vào bay), #exMpNotice (late / released / lost).
3	   late tự ẩn sau lateMs, released (khi xem) và lost (khi bay) tự ẩn sau noticeMs; nameBad giữ tới khi gõ tên khác.
4	   Không điều khiển camera hay phiên: explore/index.ts gọi exWatchShow / exWatchRender / exWatchHide và tự xử lý chuyển pha.
5	   Mọi tên người khác chỉ ghi bằng textContent, bọc trong cặp cô lập hướng chữ để tên RTL không làm lệch câu. */
6	import { CONFIG } from '../../config';
7	import { t, onChange as onLang } from '../../i18n';
8	import { exSanitizeName } from './protocol';
9	import { exRemotes } from './remote';
10	import { loadName, saveName } from './lobby';
11	import type { MultiSession } from './session';
12	
13	const $ = <T extends HTMLElement>(id: string) => document.getElementById(id) as T;
14	
15	let session: MultiSession | null = null;
16	let bound = false;
17	let pending = false;       // đã bấm vào bay, chờ máy chủ trả lời: nút khóa để không gửi hai lần
18	let pendingTimer = 0;
19	let lateUntil = 0;         // mốc (ms) hết hạn hiện exMpLate
20	let lateTimer = 0;
21	let relUntil = 0;          // mốc (ms) hết hạn hiện exMpReleased; 0 = chưa hiện trong lần xem này
22	let relTimer = 0;
23	let flyKey = '';           // thông báo khi bay đã hiện (không hiện lại sau khi tự ẩn)
24	let flyTimer = 0;
25	let rejected: string | null = null;   // tên máy chủ vừa từ chối: không dùng lại, không nhớ
26	let noticeKey = '';        // khóa đang hiện ở #exMpNotice ('' = ẩn)
27	
28	/* Tên hợp lệ đã biết: tên đã dùng trong phiên, hoặc tên nhớ ở sảnh; bỏ tên máy chủ đã từ chối */
29	const okName = (n: string): string | null => { const v = exSanitizeName(n); return v !== null && v !== rejected ? v : null; };
30	const knownName = (): string | null => (session && okName(session.name)) || okName(loadName());
31	
32	/* Ghi/ẩn #exMpNotice (dùng cả khi đang bay: mất kết nối) */
33	export function exWatchNotice(key: string): void {
34	  noticeKey = key;
35	  const el = $('exMpNotice');
36	  el.textContent = key ? t(key) : '';
37	  el.hidden = !key;
38	}
39	
40	function unlock(): void { pending = false; clearTimeout(pendingTimer); }
41	
42	/* Hiện exMpLate thêm lateMs từ bây giờ */
43	function armLate(): void {
44	  lateUntil = performance.now() + CONFIG.explore.multi.lateMs;
45	  clearTimeout(lateTimer); lateTimer = window.setTimeout(exWatchRender, CONFIG.explore.multi.lateMs + 50);
46	}
47	
48	function accept(): void {
49	  if (!session || session.phase !== 'watching' || pending) return;
50	  const input = $<HTMLInputElement>('exMpInviteName');
51	  const name = knownName() ?? exSanitizeName(input.value);
52	  if (name === null) return;
53	  pending = true; clearTimeout(pendingTimer);
54	  pendingTimer = window.setTimeout(() => { pending = false; exWatchRender(); }, CONFIG.explore.multi.pendingMs);
55	  session.join(name);   // join xóa notice cũ trước khi vẽ lại, nếu không nameBad cũ sẽ mở khóa nút ngay
56	  exWatchRender();
57	}
58	
59	export function exWatchRender(): void {
60	  const s = session;
61	  if (!s || s.phase !== 'watching') return;
62	  /* Dòng "Đang xem" */
63	  const nm = s.watched >= 0 ? exRemotes.name(s.watched) : null;
64	  const w = $('exMpWatch');
65	  w.hidden = nm === null;
66	  w.textContent = nm === null ? '' : t('exMpWatching', { name: '\u2068' + nm + '\u2069' });
67	  /* Thông báo từ phiên: nút đã có trả lời thì mở khóa */
68	  if (pending && (s.notice === 'late' || s.notice === 'nameBad')) {
69	    unlock();
70	    if (s.notice === 'late') armLate();
