1	/* ===== Dù lượn nhiều người: điều phối phía khách =====
2	   Nối MultiSession (kết nối, phiên) với exRemotes (dù người khác), nhãn tên và danh sách người bay.
3	   Chỉ mở kết nối khi có người gọi begin(); ?test mà không có multi= thì url() rỗng nên không bao giờ mở WebSocket. */
4	import { camera } from '../../core/renderer';
5	import { CONFIG } from '../../config';
6	import { t, onChange as onLang } from '../../i18n';
7	import { exConnect } from './client';
8	import { MultiSession } from './session';
9	import { exRemotes } from './remote';
10	import { exLabelsUpdate, exLabelsClear } from './labels';
11	import { ExIdle } from './idle';
12	import type { GliderState } from '../flight';
13	
14	const M = CONFIG.explore.multi;
15	let session: MultiSession | null = null;
16	let sentAt = -1e9;
17	let rosterKey = '';
18	let idle: ExIdle | null = null;
19	let idleTimer = 0, beatTimer = 0;   // setInterval kiểm tra rời máy + nhịp sống; chỉ chạy khi đang bay
20	let idleShown = '';                 // chữ đang hiện ở #exMpIdle ('' = ẩn): chỉ ghi DOM khi đổi
21	
22	/* ===== Rời máy: đếm bằng setInterval (tab ẩn vẫn đếm), hết hạn thì trả slot và sang chế độ xem ===== */
23	/* ?idleMs / ?idleWarnMs chỉ đọc khi có ?test (để test rút ngắn) */
24	function idleParams(): [number, number] {
25	  const q = new URLSearchParams(location.search);
26	  if (!q.has('test')) return [M.idleMs, M.idleWarnMs];
27	  const n = (k: string, d: number) => { const v = Number(q.get(k)); return q.has(k) && v > 0 ? v : d; };
28	  return [n('idleMs', M.idleMs), n('idleWarnMs', M.idleWarnMs)];
29	}
30	
31	function idleShow(text: string): void {
32	  const el = document.getElementById('exMpIdle');
33	  if (!el || text === idleShown) return;
34	  /* Lần đầu hiện thì đọc to một lần; các giây sau chỉ đổi chữ, không đọc lại */
35	  el.setAttribute('aria-live', idleShown === '' ? 'polite' : 'off');
36	  idleShown = text;
37	  el.textContent = text;
38	  el.hidden = text === '';
39	}
40	
41	function idleTick(): void {
42	  if (!session || !idle || session.phase !== 'flying') return;
43	  const now = performance.now();
44	  const st = idle.tick(now);
45	  if (st === 'ok') idleShow('');
46	  else if (st === 'warn') idleShow(t('exMpIdle', { s: idle.remaining(now) }));
47	  else { idleShow(''); session.leave(); }   // leave → onChange → idleStop
48	}
49	
50	function idleStart(): void {
51	  if (idleTimer || !session) return;   // đã chạy: không mở hai đồng hồ
52	  const [a, b] = idleParams();
53	  idle = new ExIdle(a, b); idle.reset(performance.now());
54	  idleShown = '';
55	  idleTimer = window.setInterval(idleTick, M.idleTickMs);
56	  beatTimer = window.setInterval(() => session?.heartbeat(), M.heartbeatMs);
57	}
58	
59	function idleStop(): void {
60	  clearInterval(idleTimer); clearInterval(beatTimer);
61	  idleTimer = beatTimer = 0; idle = null;
62	  idleShow('');
63	}
64	
65	/* Danh sách người bay ở góc màn hình: đầu "Đang bay n/5", mỗi người một dòng có chấm màu theo slot; dùng textContent */
66	function renderRoster(): void {
67	  const box = document.getElementById('exMpRoster');
68	  if (!box) return;
69	  const flyers = session ? session.flyers : [];
70	  const head = t('exMpFlying', { n: flyers.length });
71	  const key = flyers.map(f => f.slot + ':' + f.name).join('|') + '#' + (session ? session.mySlot : -1) + '#' + head;
72	  if (key === rosterKey) return;
73	  rosterKey = key;
74	  box.hidden = !session || session.phase === 'solo';
75	  box.textContent = '';
76	  const h = document.createElement('div'); h.className = 'ex-mp-head'; h.textContent = head; box.appendChild(h);
77	  for (const f of flyers) {
78	    const row = document.createElement('div'); row.className = 'ex-mp-row' + (session && f.slot === session.mySlot ? ' me' : '');
79	    const dot = document.createElement('i'); dot.style.background = M.colors[f.slot % M.colors.length];
80	    const nm = document.createElement('span'); nm.textContent = f.name;
81	    row.append(dot, nm); box.appendChild(row);
82	  }
83	}
84	
85	export const exMulti = {
86	  /* Địa chỉ máy chủ: có ?test thì ?multi= nếu có, không có thì rỗng (không mở mạng); không có ?test thì luôn là địa chỉ cấu hình (người ngoài không đổi được máy chủ qua URL) */
87	  url(): string {
88	    const q = new URLSearchParams(location.search);
89	    if (!q.has('test')) return M.url;
90	    return q.get('multi') ?? '';
91	  },
92	  get session(): MultiSession | null { return session; },
93	  onChange: (() => {}) as () => void,   // móc cho giao diện sảnh (Task 6) và test
94	
95	  /* Mở phiên; onReady gọi một lần khi có thông tin đầu tiên (sảnh hoặc ngoại tuyến). Trả false nếu không có địa chỉ */
96	  begin(onReady: () => void): boolean {
97	    const url = exMulti.url();
98	    if (!url || session) return false;
99	    const s = session = new MultiSession(() => exConnect(url, M.connectTimeoutMs));
100	    let ready = false;
101	    s.onPos = f => exRemotes.onPos(f, performance.now());
102	    s.onChange = () => {
103	      exRemotes.sync(s.flyers, s.mySlot);
104	      if (s.phase === 'solo') exLabelsClear();
105	      renderRoster();
106	      if (s.phase === 'flying') idleStart(); else idleStop();
107	      exMulti.onChange();
108	      if (!ready) { ready = true; onReady(); }
109	    };
110	    s.open();
111	    return true;
112	  },
113	
114	  /* Đóng phiên (Quay lại / Esc ở sảnh, hoặc chọn Bay một mình khi có máy chủ): đóng WebSocket, ẩn dù người khác, nhãn, danh sách; begin() mở lại được */
115	  end(): void {
116	    if (!session) return;
117	    session.dispose(); session = null;
118	    exMulti.onChange = () => {};
119	    idleStop(); exRemotes.clear(); exLabelsClear();
120	    rosterKey = ''; renderRoster();
121	  },
122	
123	  /* Mỗi khung khi đang bay: dù người khác, nhãn, gửi vị trí sendHz lần/s */
124	  update(_dt: number, nowMs: number, state: GliderState | null): void {
125	    if (!session) return;
126	    exRemotes.update(nowMs);
127	    exLabelsUpdate(camera, exRemotes, nowMs);
128	    if (state && session.phase === 'flying' && nowMs - sentAt >= 1000 / M.sendHz) {
129	      sentAt = nowMs;
130	      const p = state.pos, r = (v: number) => Math.round(v * 10) / 10, a = (v: number) => Math.round(v * 1000) / 1000;
131	      session.sendPos(r(p.x), r(p.y), r(p.z), a(state.yaw), a(state.bank), Math.round(nowMs));
132	    }
133	  },
134	
135	  /* Người bay vừa bấm phím điều khiển: đếm lại thời gian rời máy */
136	  activity(): void {
137	    if (!idle) return;
138	    idle.activity(performance.now());
139	    idleShow('');
140	  },
141	
142	  /* Trạng thái dù đang xem (khi hết chỗ, Task 6); null nếu không xem ai */
143	  watchState(): GliderState | null {
144	    return session && session.phase === 'watching' ? exRemotes.slotState(session.watched) : null;
145	  }
146	};
147	
148	onLang(() => { rosterKey = ''; renderRoster(); });
149

1	/* ===== Dù lượn nhiều người: nhãn tên nổi dưới cánh dù người khác =====
2	   Một div cho mỗi slot trong #exMpLabels. Điểm đặt nhãn thấp hơn dù labelBelow m (tên nằm dưới cánh, không che dù), ẩn khi sau camera hoặc slot chưa hiện.
3	   Chỉ ghi DOM khi chữ đổi (tên + khoảng cách, làm tươi ≤ 5 lần/s) hoặc vị trí lệch quá 1 px. Không cấp phát mỗi khung (D-018). */
4	import * as THREE from 'three';
5	import { CONFIG } from '../../config';
6	import type { exRemotes } from './remote';
7	
8	const M = CONFIG.explore.multi;
9	interface Lab { el: HTMLElement; txt: string; x: number; y: number; shown: boolean; tMs: number }
10	let labs: Lab[] | null = null;
11	const _v = new THREE.Vector3();
12	
13	function init(): Lab[] | null {
14	  const box = document.getElementById('exMpLabels');
15	  if (!box) return null;
16	  return Array.from({ length: M.slots }, () => {
17	    const el = document.createElement('div'); el.className = 'ex-mp-label'; el.hidden = true; box.appendChild(el);
18	    return { el, txt: '', x: -1e9, y: -1e9, shown: false, tMs: -1e9 };
19	  });
20	}
21	
22	// Khoảng cách làm tròn: < 1000 m ghi "NNN m", còn lại "N.N km"
23	const dist = (d: number) => d < 1000 ? `${Math.round(d)} m` : `${(d / 1000).toFixed(1)} km`;
24	
25	export function exLabelsUpdate(camera: THREE.Camera, remotes: typeof exRemotes, nowMs: number): void {
26	  if (!labs && !(labs = init())) return;
27	  const w = window.innerWidth, h = window.innerHeight;
28	  for (let i = 0; i < labs.length; i++) {
29	    const L = labs[i], st = remotes.slotState(i);
30	    let vis = false;
31	    if (st) {
32	      _v.set(st.pos.x, st.pos.y - M.labelBelow, st.pos.z).applyMatrix4(camera.matrixWorldInverse);
33	      if (-_v.z > 0.1) {   // trước camera
34	        _v.applyMatrix4(camera.projectionMatrix);
35	        const px = (_v.x * 0.5 + 0.5) * w, py = (-_v.y * 0.5 + 0.5) * h;
36	        if (px > -80 && px < w + 80 && py > -40 && py < h + 40) {
37	          vis = true;
38	          if (nowMs - L.tMs >= 200) {
39	            L.tMs = nowMs;
40	            const txt = `${remotes.name(i)} · ${dist(Math.hypot(st.pos.x - camera.position.x, st.pos.y - camera.position.y, st.pos.z - camera.position.z))}`;
41	            if (txt !== L.txt) { L.txt = txt; L.el.textContent = txt; }
42	          }
43	          if (Math.abs(px - L.x) > 1 || Math.abs(py - L.y) > 1) { L.x = px; L.y = py; L.el.style.transform = `translate(${px.toFixed(0)}px,${py.toFixed(0)}px) translateX(-50%)`; }
44	        }
45	      }
46	    }
47	    if (vis !== L.shown) { L.shown = vis; L.el.hidden = !vis; }
48	  }
49	}
50	
51	/* Ẩn hết nhãn (rời phòng) */
52	export function exLabelsClear(): void {
53	  if (!labs) return;
54	  for (const L of labs) { L.shown = false; L.el.hidden = true; L.x = L.y = -1e9; }
55	}
56

1	/* ===== Dù lượn nhiều người: bước chọn slot và nhập tên (trong hộp thoại #chooser) =====
2	   Hiện sau khi bấm thẻ Dù lượn lúc có máy chủ: 5 chấm + "Còn N trên 5 chỗ", tên những người đang bay, ô tên, nút Bay ngay.
3	   Cập nhật trực tiếp theo MultiSession; tên người khác chỉ ghi bằng textContent. Tên của mình nhớ ở localStorage.
4	   Pha lobby: cho nhập tên và giành chỗ. Pha solo (không kết nối được): báo ngoại tuyến. Nút Bay một mình hiện ở cả hai pha (đóng phiên rồi bay một mình).
5	   Pha flying: gọi onFly. Pha watching (hết chỗ): gọi onWatch (chế độ xem do Task 7 làm).
6	   Nút Quay lại hoặc Esc: đóng phiên (đóng WebSocket), trả lại các thẻ, tiêu đề và aria-labelledby, gọi onBack để chọn lại.
7	   Trình nghe gắn một lần cho cả trang và đọc sảnh đang mở (cur), nên vào sảnh nhiều lần không nhân đôi. */
8	import { CONFIG } from '../../config';
9	import { t, onChange as onLang } from '../../i18n';
10	import { exMulti } from './index';
11	import { exSanitizeName } from './protocol';
12	import type { MultiSession } from './session';
13	
14	export interface LobbyCallbacks { onFly: () => void; onWatch: () => void; onSolo: () => void; onBack: () => void }
15	
16	const M = CONFIG.explore.multi;
17	const NAME_KEY = 'exMpName';
18	const $ = <T extends HTMLElement>(id: string) => document.getElementById(id) as T;
19	
20	export function loadName(): string { try { return localStorage.getItem(NAME_KEY) || ''; } catch { return ''; } }
21	export function saveName(n: string): void { try { localStorage.setItem(NAME_KEY, n); } catch { /* bộ nhớ trình duyệt bị chặn */ } }
22	
23	let listKey = '';
24	let bound = false;
25	let cur: { session: MultiSession; cb: LobbyCallbacks } | null = null;   // sảnh đang mở; null = đã đóng (vào bay, xem, bay một mình, quay lại)
26	
27	/* Đóng sảnh rồi gọi f (một lần) */
28	function finish(f: () => void): void {
29	  if (!cur) return;
30	  cur = null; exMulti.onChange = () => {};
31	  f();
32	}
33	
34	/* Trả hộp thoại về các thẻ: hiện tiêu đề, gắn lại aria-labelledby */
35	function restoreCards(): void {
36	  const root = $('exMpLobby'), box = root.closest('#chooser') as HTMLElement;
37	  root.hidden = true;
38	  box.querySelector<HTMLElement>('.ex-cards')!.hidden = false;
39	  $('exTitle').hidden = false;
40	  box.setAttribute('aria-labelledby', 'exTitle');
41	}
42	
43	/* Quay lại / Esc: đóng phiên và về các thẻ */
44	function back(): void {
45	  const c = cur; if (!c) return;
46	  finish(() => { exMulti.end(); restoreCards(); c.cb.onBack(); });
47	}
48	
49	/* Bay một mình (có hay không có máy chủ): đóng phiên để không gửi/nhận gì */
50	function solo(): void {
51	  const c = cur; if (!c) return;
52	  finish(() => { exMulti.end(); c.cb.onSolo(); });
53	}
54	
55	function render(): void {
56	  if (!cur) return;
57	  const session = cur.session, cb = cur.cb;
58	  const fly = $<HTMLButtonElement>('exMpFly'), soloBtn = $<HTMLButtonElement>('exMpSolo'), input = $<HTMLInputElement>('exMpNameIn');
59	  const ph = session.phase;
60	  if (ph === 'flying') { finish(cb.onFly); return; }
61	  if (ph === 'watching') { finish(cb.onWatch); return; }
62	  const offline = ph === 'solo';
63	  $('exMpOnline').hidden = offline;
64	  $('exMpOffline').hidden = !offline;
65	  soloBtn.classList.toggle('ex-mp-alt', !offline);   // có máy chủ: nút phụ; ngoại tuyến: nút chính
66	  if (offline) { if (document.activeElement !== soloBtn) soloBtn.focus({ preventScroll: true }); return; }
67	  const ready = ph === 'lobby';
68	  const free = M.slots - session.flyers.length;
69	  $('exMpSeats').textContent = ready ? t('exMpSeats', { n: free }) : '…';
70	  $('exMpNameHint').textContent = t('exMpNameMax', { n: M.nameMax });
71	  const taken = new Set(session.flyers.map(f => f.slot));
72	  $('exMpDots').querySelectorAll<HTMLElement>('i').forEach((d, i) => {
73	    d.classList.toggle('on', taken.has(i));
74	    d.style.background = taken.has(i) ? M.colors[i % M.colors.length] : '';
75	  });
76	  const key = session.flyers.map(f => f.slot + ':' + f.name).join('|');
77	  if (key !== listKey) {
78	    listKey = key;
79	    const list = $('exMpList'); list.textContent = '';
80	    for (const f of session.flyers) {
81	      const row = document.createElement('div'); row.className = 'ex-mp-row';
82	      const dot = document.createElement('i'); dot.style.background = M.colors[f.slot % M.colors.length];
83	      const nm = document.createElement('span'); nm.textContent = f.name; nm.dir = 'auto';
84	      row.append(dot, nm); list.appendChild(row);
85	    }
86	  }
87	  $('exMpNameBad').hidden = session.notice !== 'nameBad';
88	  fly.disabled = !ready || exSanitizeName(input.value) === null;
89	}
90	
91	function go(): void {
92	  if (!cur) return;
93	  const name = exSanitizeName($<HTMLInputElement>('exMpNameIn').value);
94	  if (name === null || cur.session.phase !== 'lobby') return;
95	  saveName(name);
96	  cur.session.join(name);
97	}
98	
99	/* Gắn trình nghe một lần */
100	function bind(): void {
101	  if (bound) return;
102	  bound = true;
103	  const root = $('exMpLobby'), box = root.closest('#chooser') as HTMLElement, input = $<HTMLInputElement>('exMpNameIn');
104	  input.addEventListener('input', () => {
105	    if (!cur) return;
106	    $('exMpNameBad').hidden = true;
107	    const ok = exSanitizeName(input.value);
108	    if (ok !== null) saveName(ok);   // nhớ ngay khi hợp lệ, tải lại trang vẫn còn
109	    $<HTMLButtonElement>('exMpFly').disabled = cur.session.phase !== 'lobby' || ok === null;
110	  });
111	  input.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); go(); } });
112	  $('exMpFly').addEventListener('click', go);
113	  $('exMpSolo').addEventListener('click', solo);
114	  $('exMpBack').addEventListener('click', back);
115	  box.addEventListener('keydown', (e) => { if (e.key === 'Escape' && cur) { e.preventDefault(); back(); } });
116	  onLang(() => render());
117	}
118	
119	/* Hiện bước riêng thay cho các thẻ và gắn nó vào phiên; trả ngay (phiên đang ở pha 'connecting') */
120	export function exShowLobby(session: MultiSession, cb: LobbyCallbacks): void {
121	  bind();
122	  const root = $('exMpLobby'), box = root.closest('#chooser') as HTMLElement, input = $<HTMLInputElement>('exMpNameIn');
123	  box.querySelector<HTMLElement>('.ex-cards')!.hidden = true;
124	  $('exTitle').hidden = true; $('exMpLostNote').hidden = true;
125	  box.setAttribute('aria-labelledby', 'exMpSky');
126	  root.hidden = false;
127	  if (!input.value) input.value = loadName();
128	  listKey = '';
129	  cur = { session, cb };
130	  exMulti.onChange = render;
131	  render();
132	  input.focus({ preventScroll: true });
133	}
134

1	/* ===== Dù lượn nhiều người: giao diện chế độ xem và các thông báo =====
2	   #exMpWatch "Đang xem: tên", #exMpInvite (lời mời khi còn chỗ: ô tên nếu chưa có tên hợp lệ + nút vào bay), #exMpNotice (late / released / lost).
3	   late tự ẩn sau lateMs, released (khi xem) và lost (khi bay) tự ẩn sau noticeMs; nameBad giữ tới khi gõ tên khác.
4	   Không điều khiển camera hay phiên: explore/index.ts gọi exWatchShow / exWatchRender / exWatchHide và tự xử lý chuyển pha.
5	   Mọi tên người khác chỉ ghi bằng textContent, bọc trong cặp cô lập hướng chữ để tên RTL không làm lệch câu. */
6	import { CONFIG } from '../../config';
7	import { t, onChange as onLang } from '../../i18n';
8	import { exSanitizeName } from './protocol';
9	import { exRemotes } from './remote';
10	import { loadName, saveName } from './lobby';
11	import type { MultiSession } from './session';
12	
13	const $ = <T extends HTMLElement>(id: string) => document.getElementById(id) as T;
14	
15	let session: MultiSession | null = null;
16	let bound = false;
17	let pending = false;       // đã bấm vào bay, chờ máy chủ trả lời: nút khóa để không gửi hai lần
18	let pendingTimer = 0;
19	let lateUntil = 0;         // mốc (ms) hết hạn hiện exMpLate
20	let lateTimer = 0;
21	let relUntil = 0;          // mốc (ms) hết hạn hiện exMpReleased; 0 = chưa hiện trong lần xem này
22	let relTimer = 0;
23	let flyKey = '';           // thông báo khi bay đã hiện (không hiện lại sau khi tự ẩn)
24	let flyTimer = 0;
25	let rejected: string | null = null;   // tên máy chủ vừa từ chối: không dùng lại, không nhớ
26	let noticeKey = '';        // khóa đang hiện ở #exMpNotice ('' = ẩn)
27	
28	/* Tên hợp lệ đã biết: tên đã dùng trong phiên, hoặc tên nhớ ở sảnh; bỏ tên máy chủ đã từ chối */
29	const okName = (n: string): string | null => { const v = exSanitizeName(n); return v !== null && v !== rejected ? v : null; };
30	const knownName = (): string | null => (session && okName(session.name)) || okName(loadName());
31	
32	/* Ghi/ẩn #exMpNotice (dùng cả khi đang bay: mất kết nối) */
33	export function exWatchNotice(key: string): void {
34	  noticeKey = key;
35	  const el = $('exMpNotice');
36	  el.textContent = key ? t(key) : '';
37	  el.hidden = !key;
38	}
39	
40	function unlock(): void { pending = false; clearTimeout(pendingTimer); }
41	
42	/* Hiện exMpLate thêm lateMs từ bây giờ */
43	function armLate(): void {
44	  lateUntil = performance.now() + CONFIG.explore.multi.lateMs;
45	  clearTimeout(lateTimer); lateTimer = window.setTimeout(exWatchRender, CONFIG.explore.multi.lateMs + 50);
46	}
47	
48	function accept(): void {
49	  if (!session || session.phase !== 'watching' || pending) return;
50	  const input = $<HTMLInputElement>('exMpInviteName');
51	  const name = knownName() ?? exSanitizeName(input.value);
52	  if (name === null) return;
53	  pending = true; clearTimeout(pendingTimer);
54	  pendingTimer = window.setTimeout(() => { pending = false; exWatchRender(); }, CONFIG.explore.multi.pendingMs);
55	  session.join(name);   // join xóa notice cũ trước khi vẽ lại, nếu không nameBad cũ sẽ mở khóa nút ngay
56	  exWatchRender();
57	}
58	
59	export function exWatchRender(): void {
60	  const s = session;
61	  if (!s || s.phase !== 'watching') return;
62	  /* Dòng "Đang xem" */
63	  const nm = s.watched >= 0 ? exRemotes.name(s.watched) : null;
64	  const w = $('exMpWatch');
65	  w.hidden = nm === null;
66	  w.textContent = nm === null ? '' : t('exMpWatching', { name: '\u2068' + nm + '\u2069' });
67	  /* Thông báo từ phiên: nút đã có trả lời thì mở khóa */
68	  if (pending && (s.notice === 'late' || s.notice === 'nameBad')) {
69	    unlock();
70	    if (s.notice === 'late') armLate();
71	  }
72	  if (s.notice === 'nameBad' && s.name !== rejected) {   // tên bị từ chối: quên tên đó (cả bản đã nhớ), hiện lại ô nhập để gõ tên khác
73	    rejected = s.name;
74	    if (exSanitizeName(loadName()) === rejected) saveName('');
75	    $<HTMLInputElement>('exMpInviteName').value = '';
76	  }
77	  let key = '';
78	  if (s.notice === 'late') key = performance.now() < lateUntil ? 'exMpLate' : '';
79	  else if (s.notice === 'released') {
80	    const now = performance.now();
81	    if (!relUntil) { relUntil = now + CONFIG.explore.multi.noticeMs; clearTimeout(relTimer); relTimer = window.setTimeout(exWatchRender, CONFIG.explore.multi.noticeMs + 50); }
82	    key = now < relUntil ? 'exMpReleased' : '';
83	  }
84	  else if (s.notice === 'nameBad') key = 'exMpNameBad';
85	  exWatchNotice(key);
86	  /* Lời mời */
87	  const inv = $('exMpInvite'), input = $<HTMLInputElement>('exMpInviteName'), btn = $<HTMLButtonElement>('exMpInviteFly');
88	  inv.hidden = !s.invite;
89	  const needName = knownName() === null;
90	  input.hidden = !needName;
91	  btn.disabled = pending || (needName && exSanitizeName(input.value) === null);
92	}
93	
94	/* Bắt đầu hiện giao diện xem cho phiên s */
95	export function exWatchShow(s: MultiSession): void {
96	  session = s; unlock(); lateUntil = 0; relUntil = 0; rejected = null;
97	  if (s.notice === 'late') armLate();   // bị giành chỗ ngay ở sảnh: vào xem kèm lý do
98	  if (!bound) {
99	    bound = true;
100	    $('exMpInviteFly').addEventListener('click', accept);
101	    const input = $<HTMLInputElement>('exMpInviteName');
102	    input.addEventListener('input', exWatchRender);
103	    input.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); accept(); } });   // Esc để lọt lên trình nghe chung (thoát)
104	    onLang(() => { if (session) { exWatchRender(); if (noticeKey && session.phase !== 'watching') exWatchNotice(noticeKey); } });
105	  }
106	  exWatchRender();
107	}
108	
109	/* Gỡ giao diện xem (vào bay, hoặc thoát) */
110	export function exWatchHide(): void {
111	  if (session && session.phase === 'flying') { const n = exSanitizeName(session.name); if (n !== null) saveName(n); }   // máy chủ đã nhận tên: bấy giờ mới nhớ
112	  session = null; unlock(); clearTimeout(lateTimer); clearTimeout(relTimer);
113	  $('exMpWatch').hidden = true; $('exMpInvite').hidden = true;
114	  exWatchNotice('');
115	}
116	
117	/* Khi đang bay: hiện một thông báo (mất kết nối) một lần, tự ẩn sau noticeMs; đổi ngôn ngữ thì dịch lại */
118	export function exFlyNotice(s: MultiSession, key: string): void {
119	  session = s;   // để onLang dịch lại
120	  if (key === flyKey) return;
121	  flyKey = key;
122	  exWatchNotice(key);
123	  clearTimeout(flyTimer);
124	  if (key) flyTimer = window.setTimeout(() => { if (noticeKey === key) exWatchNotice(''); }, CONFIG.explore.multi.noticeMs);
125	}
126

1	/* ============================ Tự khám phá: màn chọn phương tiện ============================
2	   Lớp phủ HTML (#chooser trong index.html), không thêm gì vào cảnh. Hiện sau khung đầu tiên (cảnh đã dựng phía sau)
3	   và chặn chuột vào canvas tới khi chọn. Chữ do data-i18n lo; ở đây chỉ khóa thẻ và gọi onPick. */
4	
5	import { getLang, onChange } from '../i18n';
6	import { exMulti } from './multi';
7	import { exShowLobby } from './multi/lobby';
8	
9	export type ExChoice = 'glider' | 'guided';
10	
11	const el = () => document.getElementById('chooser');
12	
13	/* Dù lượn cần bàn phím: thiết bị cảm ứng (không có hover) thì khóa thẻ và hiện nhãn "Chỉ dùng trên máy tính" */
14	function lockGliderOnTouch(root: HTMLElement): void {
15	  if (!window.matchMedia('(hover: none)').matches) return;
16	  const card = root.querySelector<HTMLButtonElement>('[data-pick="glider"]');
17	  if (!card) return;
18	  card.disabled = true;
19	  card.querySelector<HTMLElement>('.ex-note')?.removeAttribute('hidden');
20	}
21	
22	/* Ô ngôn ngữ riêng của màn chọn (lớp phủ che #langSelect): chép danh sách từ #langSelect, đổi thì chuyển cho #langSelect xử lý */
23	function wireLang(root: HTMLElement): void {
24	  const mine = root.querySelector<HTMLSelectElement>('#exLang');
25	  const main = document.getElementById('langSelect') as HTMLSelectElement | null;
26	  if (!mine || !main) return;
27	  mine.innerHTML = main.innerHTML; mine.value = getLang();
28	  mine.addEventListener('change', () => { main.value = mine.value; main.dispatchEvent(new Event('change')); });
29	  onChange((code) => { mine.value = code; });
30	}
31	
32	/* Màn chọn là hộp thoại modal: các khối giao diện cũ (header, panel, canvas...) đặt inert để Tab/Enter không lọt xuống dưới */
33	const inerted: HTMLElement[] = [];
34	function setUnderInert(root: HTMLElement, on: boolean): void {
35	  if (on) {
36	    for (const c of Array.from(document.body.children) as HTMLElement[]) {
37	      if (c === root || c.tagName === 'SCRIPT' || c.id === 'loading' || c.inert) continue;
38	      c.inert = true; inerted.push(c);
39	    }
40	  } else { for (const c of inerted) c.inert = false; inerted.length = 0; }
41	}
42	
43	export function exShowChooser(onPick: (choice: ExChoice) => void, onWatch: () => void = () => {}): void {
44	  const root = el();
45	  if (!root) return;
46	  lockGliderOnTouch(root);
47	  /* Lần trước mất kết nối khi đang xem (explore.exit tải lại trang): đọc cờ một lần rồi xóa, hiện exMpLostChooser */
48	  try { if (sessionStorage.getItem('exMpNotice') === 'lost') { sessionStorage.removeItem('exMpNotice'); const n = document.getElementById('exMpLostNote'); if (n) n.hidden = false; } } catch { /* bộ nhớ bị chặn */ }
49	  wireLang(root);
50	  /* Không dùng { once: true }: từ sảnh bấm Quay lại / Esc thì các thẻ phải chọn lại được. Hộp đã đóng (đã chọn xong) thì bỏ qua */
51	  root.querySelectorAll<HTMLButtonElement>('button[data-pick]').forEach((b) => {
52	    if (b.disabled) return;
53	    b.addEventListener('click', () => {
54	      if (root.hidden) return;
55	      const choice = b.dataset.pick as ExChoice;
56	      /* Dù lượn có máy chủ: sang bước chọn slot + nhập tên (mở kết nối ở đây, không sớm hơn); không có máy chủ: bay một mình ngay như trước */
57	      if (choice === 'glider' && exMulti.begin(() => {})) {
58	        const solo = () => { exHideChooser(); onPick('glider'); };
59	        exShowLobby(exMulti.session!, { onFly: solo, onWatch: () => { exHideChooser(); onWatch(); }, onSolo: solo, onBack: () => b.focus({ preventScroll: true }) });
60	        return;
61	      }
62	      exHideChooser(); onPick(choice);
63	    });
64	  });
65	  const show = () => { root.hidden = false; setUnderInert(root, true); root.querySelector<HTMLButtonElement>('button[data-pick]:not(:disabled)')?.focus({ preventScroll: true }); };
66	  const loading = document.getElementById('loading');
67	  if (!loading || loading.classList.contains('done')) { show(); return; }
68	  const mo = new MutationObserver(() => { if (loading.classList.contains('done')) { mo.disconnect(); show(); } });   // #loading.done được đặt sau khung đầu
69	  mo.observe(loading, { attributes: true, attributeFilter: ['class'] });
70	}
71	
72	export function exHideChooser(): void {
73	  const root = el();
74	  if (root) { root.hidden = true; setUnderInert(root, false); }
75	}
