1	/* ============================ Tự khám phá: màn chọn phương tiện ============================
2	   Lớp phủ HTML (#chooser trong index.html), không thêm gì vào cảnh. Hiện sau khung đầu tiên (cảnh đã dựng phía sau)
3	   và chặn chuột vào canvas tới khi chọn. Chữ do data-i18n lo; ở đây chỉ khóa thẻ và gọi onPick. */
4	
5	import { getLang, onChange } from '../i18n';
6	import { exMulti } from './multi';
7	import { exShowLobby } from './multi/lobby';
8	
9	export type ExChoice = 'glider' | 'guided';
10	
11	const el = () => document.getElementById('chooser');
12	
13	/* Dù lượn cần bàn phím: thiết bị cảm ứng (không có hover) thì khóa thẻ và hiện nhãn "Chỉ dùng trên máy tính" */
14	function lockGliderOnTouch(root: HTMLElement): void {
15	  if (!window.matchMedia('(hover: none)').matches) return;
16	  const card = root.querySelector<HTMLButtonElement>('[data-pick="glider"]');
17	  if (!card) return;
18	  card.disabled = true;
19	  card.querySelector<HTMLElement>('.ex-note')?.removeAttribute('hidden');
20	}
21	
22	/* Ô ngôn ngữ riêng của màn chọn (lớp phủ che #langSelect): chép danh sách từ #langSelect, đổi thì chuyển cho #langSelect xử lý */
23	function wireLang(root: HTMLElement): void {
24	  const mine = root.querySelector<HTMLSelectElement>('#exLang');
25	  const main = document.getElementById('langSelect') as HTMLSelectElement | null;
26	  if (!mine || !main) return;
27	  mine.innerHTML = main.innerHTML; mine.value = getLang();
28	  mine.addEventListener('change', () => { main.value = mine.value; main.dispatchEvent(new Event('change')); });
29	  onChange((code) => { mine.value = code; });
30	}
31	
32	/* Màn chọn là hộp thoại modal: các khối giao diện cũ (header, panel, canvas...) đặt inert để Tab/Enter không lọt xuống dưới */
33	const inerted: HTMLElement[] = [];
34	function setUnderInert(root: HTMLElement, on: boolean): void {
35	  if (on) {
36	    for (const c of Array.from(document.body.children) as HTMLElement[]) {
37	      if (c === root || c.tagName === 'SCRIPT' || c.id === 'loading' || c.inert) continue;
38	      c.inert = true; inerted.push(c);
39	    }
40	  } else { for (const c of inerted) c.inert = false; inerted.length = 0; }
41	}
42	
43	export function exShowChooser(onPick: (choice: ExChoice) => void, onWatch: () => void = () => {}): void {
44	  const root = el();
45	  if (!root) return;
46	  lockGliderOnTouch(root);
47	  /* Lần trước mất kết nối khi đang xem (explore.exit tải lại trang): đọc cờ một lần rồi xóa, hiện exMpLostChooser */
48	  try { if (sessionStorage.getItem('exMpNotice') === 'lost') { sessionStorage.removeItem('exMpNotice'); const n = document.getElementById('exMpLostNote'); if (n) n.hidden = false; } } catch { /* bộ nhớ bị chặn */ }
49	  wireLang(root);
50	  /* Không dùng { once: true }: từ sảnh bấm Quay lại / Esc thì các thẻ phải chọn lại được. Hộp đã đóng (đã chọn xong) thì bỏ qua */
51	  root.querySelectorAll<HTMLButtonElement>('button[data-pick]').forEach((b) => {
52	    if (b.disabled) return;
53	    b.addEventListener('click', () => {
54	      if (root.hidden) return;
55	      const choice = b.dataset.pick as ExChoice;
56	      /* Dù lượn có máy chủ: sang bước chọn slot + nhập tên (mở kết nối ở đây, không sớm hơn); không có máy chủ: bay một mình ngay như trước */
57	      if (choice === 'glider' && exMulti.begin(() => {})) {
58	        const solo = () => { exHideChooser(); onPick('glider'); };
59	        exShowLobby(exMulti.session!, { onFly: solo, onWatch: () => { exHideChooser(); onWatch(); }, onSolo: solo, onBack: () => b.focus({ preventScroll: true }) });
60	        return;
61	      }
62	      exHideChooser(); onPick(choice);
63	    });
64	  });
65	  const show = () => { root.hidden = false; setUnderInert(root, true); root.querySelector<HTMLButtonElement>('button[data-pick]:not(:disabled)')?.focus({ preventScroll: true }); };
66	  const loading = document.getElementById('loading');
67	  if (!loading || loading.classList.contains('done')) { show(); return; }
68	  const mo = new MutationObserver(() => { if (loading.classList.contains('done')) { mo.disconnect(); show(); } });   // #loading.done được đặt sau khung đầu
69	  mo.observe(loading, { attributes: true, attributeFilter: ['class'] });
70	}
71	
72	export function exHideChooser(): void {
73	  const root = el();
74	  if (root) { root.hidden = true; setUnderInert(root, false); }
75	}
76

1	/* ============================ Tự khám phá: điều phối chế độ bay dù lượn ============================
2	   Nối flight (mô hình), glider (dù), chase (camera) với vòng animate, phím và URL.
3	   `?explore=glider` bay thẳng; không tham số (hoặc `?test&chooser`) hiện màn chọn; Esc tải lại trang không còn tham số explore. Camera do explore.update đặt sau updateCamera. */
4	import * as THREE from 'three';
5	import { scene, camera, controls } from '../core/renderer';
6	import { cam, keys } from '../views/state';
7	import { exCreate, exStep, exInputFromKeys, type GliderState, type GliderInput } from './flight';
8	import { exBuildGlider, exPlaceGlider } from './glider';
9	import { exChase } from './chase';
10	import { exShowChooser } from './chooser';
11	import { exNight, exNightBind, exNightStep } from './nightShows';
12	import { exMulti } from './multi';
13	import { stroll, setupStroll } from './stroll';
14	import { exWatchShow, exWatchHide, exWatchRender, exFlyNotice } from './multi/watch';
15	import { CONFIG } from '../config';
16	import type { SwingController } from '../bridges/song-han/SwingController';
17	
18	const _inp: GliderInput = { turn: 0, climb: 0, throttle: 0 };   // đầu vào tái dùng mỗi khung
19	
20	let glider: THREE.Group | null = null;
21	let state: GliderState | null = null;
22	let watching = false;   // đang xem người khác bay (hết chỗ hoặc vừa nhường chỗ): không có dù của mình, không đọc phím
23	let chased = false;     // camera đã bám người được xem lần nào chưa (lần đầu đặt thẳng, không trượt từ xa)
24	let readout = '';   // chữ đang hiện ở #exSpeed: chỉ ghi DOM khi đổi
25	
26	const active = () => cam.mode === 'glider' && state !== null;
27	const inGlider = () => active() || watching;   // Esc và giao diện bay áp cho cả chế độ xem
28	
29	/* Mỗi khung khi xem: dù người khác, nhãn, danh sách; camera bám dù đang xem (không có người thì giữ nguyên) */
30	function watchStep(dt: number): void {
31	  exMulti.update(dt, performance.now(), null);
32	  const st = exMulti.watchState();
33	  if (st) { exChase(camera, controls.target, st, dt, !chased); chased = true; }
34	  exNightStep(dt);
35	}
36	
37	/* Đổi phiên khi đang xem hoặc bay: vào bay, mất kết nối, bị thu hồi chỗ */
38	function onMultiChange(): void {
39	  const s = exMulti.session; if (!s) return;
40	  if (watching) {
41	    if (s.phase === 'flying') { explore.start(); return; }   // chấp nhận lời mời: cất cánh mới như bay thường
42	    if (s.phase === 'solo') { try { sessionStorage.setItem('exMpNotice', 'lost'); } catch { /* bộ nhớ bị chặn */ } explore.exit(); return; }   // màn chọn đọc cờ này và hiện exMpLost
43	    exWatchRender();
44	  } else if (active()) {
45	    if (s.phase === 'watching') { state = null; if (glider) glider.visible = false; explore.startWatching(true); return; }   // chỗ bị thu hồi: sang xem, camera giữ nguyên
46	    if (s.phase === 'solo' && s.notice === 'lost') exFlyNotice(s, 'exMpLost');   // vẫn bay, người khác đã biến mất
47	  }
48	}
