140	  if (q.has('test')) document.body.classList.add('ex-test');   // giữ HUD khi bay để test đo draw call
141	  document.getElementById('btnExExit')?.addEventListener('click', () => explore.exit());
142	  if (q.get('explore') === 'glider') { explore.start(); return; }
143	  if (q.get('explore') === 'stroll') { stroll.start(); return; }   // đi dạo một mình (màn chọn mở thẻ Đi dạo ở Task 7)
144	  if (!q.has('test') || q.has('chooser')) exShowChooser((choice) => { if (choice === 'glider') explore.start(); }, () => explore.startWatching());   // 'guided': màn chọn tự ẩn, giao diện cũ
