1	/* ============================ Đi dạo: điều phối chế độ (một mình, máy tính) ============================
2	   Nối bản đồ va chạm (map / mapData / sceneData), chuyển động (motion), nhân vật (avatars), camera sau lưng (camera) với vòng animate, phím, chuột.
3	   `?explore=stroll` vào thẳng (explore/index.ts gọi start). Esc và nút Thoát dùng explore.exit() (tải lại trang, D-020).
4	   - Bản đồ dựng lần đầu vào chế độ: dữ liệu tĩnh + nhà / chân đế thu từ cảnh đã dựng (chỉ đọc, sau mọi rand()).
5	   - Nhịp quay Cầu sông Hàn đóng với người đi dạo khi cầu rời trạng thái CLOSED (spec §3 mục 13); không tự quay, không tăng tốc quay.
6	   - Ban đêm Cầu Rồng tự phun như khi bay dù (exNightStep, không đụng cầu quay).
7	   - Nhảy theo cạnh: một lần bấm Space một lần nhảy, giữ Space không nhảy liên tục (stStep nhảy mỗi khung jump = true khi chạm đất).
8	   - Phím chỉ ghi khi đang đi dạo, bỏ qua ô nhập và tổ hợp Ctrl / Meta / Alt; blur, ẩn tab, focus vào ô nhập thì xóa hết phím (Review Focus 3).
9	   Mỗi khung không cấp phát (D-018). */
10	import { scene, camera, controls, canvas } from '../../core/renderer';
11	import { cam, keys } from '../../views/state';
12	import { CONFIG } from '../../config';
13	import { stSetGate, type StMap } from './map';
14	import { ST_GATE_SWING, stBuildStaticMap } from './mapData';
15	import { stCreate, stStep, type StState, type StInput } from './motion';
16	import { stAvatars } from './avatars';
17	import { stCollectRuntime } from './sceneData';
18	import { stCamPlace, stCamDrag, type StCam } from './camera';
19	import { stInputFromKeys } from './keys';
20	import { exNightStep } from '../nightShows';
21	import type { SwingController } from '../../bridges/song-han/SwingController';
22	
23	const ST_SOLO_SLOT = -1;     // stCreate / stSpawn: đi một mình đứng giữa các điểm xuất phát
24	const ST_SOLO_AVATAR = 0;    // instance nhân vật khi đi một mình (avatars.ts)
25	
26	let map: StMap | null = null;
27	let state: StState | null = null;
28	let ctrl: SwingController | null = null;
29	let jumpQueued = false;      // Space vừa được bấm (không phải tự lặp): khung sau nhảy một lần
30	const camS: StCam = { yaw: 0, pitch: CONFIG.stroll.cam.pitch };
31	const _inp: StInput = { mx: 0, mz: 0, run: false, jump: false, camYaw: 0 };   // đầu vào tái dùng mỗi khung
32	
33	const active = () => cam.mode === 'stroll' && state !== null;
34	const isField = (t: EventTarget | null) => !!t && /^(SELECT|INPUT|TEXTAREA)$/.test((t as HTMLElement).tagName || '');
35	
36	/* Một bước: cổng nhịp quay, chuyển động, nhân vật, camera, hiệu ứng đêm */
37	function advance(dt: number, inp: StInput): void {
38	  if (ctrl) stSetGate(map!, ST_GATE_SWING, ctrl.state !== 'CLOSED');
39	  stStep(state!, inp, map!, dt);
40	  stAvatars.setSelf(ST_SOLO_AVATAR, state);
41	  stCamPlace(camera, controls.target, state!, camS, map!, dt);
42	  exNightStep(dt, false);
43	}
44	
45	export const stroll = {
46	  active,
47	  get state(): StState | null { return state; },
48	  get map(): StMap | null { return map; },
49	  get cam(): StCam { return camS; },
50	  start(): void {
51	    if (!map) { map = stBuildStaticMap(); stCollectRuntime(map); }
52	    if (ctrl) stSetGate(map, ST_GATE_SWING, ctrl.state !== 'CLOSED');
53	    state = stCreate(map, ST_SOLO_SLOT);
54	    camS.yaw = state.yaw; camS.pitch = CONFIG.stroll.cam.pitch;
55	    const mesh = stAvatars.build();
56	    if (!mesh.parent) scene.add(mesh);
57	    stAvatars.setSelf(ST_SOLO_AVATAR, state);
58	    keys.clear(); jumpQueued = false;
59	    cam.flight.then = null; cam.mode = 'stroll'; controls.enabled = false;
60	    stCamPlace(camera, controls.target, state, camS, map, 0, true);
61	    document.body.classList.add('explore', 'stroll');
62	  },
63	  update(dt: number): void {
64	    if (!active()) return;
65	    stInputFromKeys(keys, camS.yaw, _inp);
66	    _inp.jump = jumpQueued; jumpQueued = false;
67	    advance(dt, _inp);
68	  },
69	  /* Cho test: như update nhưng nhận đầu vào trực tiếp */
70	  step(dt: number, inp: StInput): void {
71	    if (active()) advance(dt, inp);
72	  }
73	};
74	
75	export function setupStroll(c: SwingController): void {
76	  ctrl = c;
77	  window.addEventListener('keydown', (e) => {
78	    if (!active() || e.key === 'Escape') return;   // Esc do explore/index.ts xử lý (thoát chung)
79	    if (e.ctrlKey || e.metaKey || e.altKey) return;   // phím tắt trình duyệt không điều khiển nhân vật, tránh kẹt phím
80	    if (isField(e.target)) return;                    // gõ trong ô nhập / chọn không điều khiển nhân vật
81	    const k = e.key.toLowerCase();
82	    if (k === ' ') { e.preventDefault(); if (!e.repeat) jumpQueued = true; }
83	    else if (k.startsWith('arrow')) e.preventDefault();
84	    keys.add(k);
85	  });
86	  window.addEventListener('keyup', (e) => {
87	    keys.delete(e.key.toLowerCase());
88	    if (e.key === ' ' && active() && !isField(e.target)) e.preventDefault();   // Space không bấm nút đang focus
89	  });
90	  const drop = () => { keys.clear(); jumpQueued = false; };
91	  window.addEventListener('blur', drop);
92	  document.addEventListener('visibilitychange', () => { if (document.hidden) drop(); });
93	  window.addEventListener('focusin', (e) => { if (active() && isField(e.target)) drop(); });
94	  /* Kéo chuột trái trên canvas: xoay camera (cảm ứng ở Task 8) */
95	  let dragId = -1, lx = 0, ly = 0;
96	  canvas.addEventListener('pointerdown', (e) => {
97	    if (!active() || e.pointerType === 'touch' || e.button !== 0) return;
98	    dragId = e.pointerId; lx = e.clientX; ly = e.clientY;
99	    canvas.setPointerCapture(e.pointerId);
100	  });
101	  canvas.addEventListener('pointermove', (e) => {
102	    if (e.pointerId !== dragId) return;
103	    stCamDrag(camS, e.clientX - lx, e.clientY - ly, CONFIG.stroll.cam.mouse);
104	    lx = e.clientX; ly = e.clientY;
105	  });
106	  const end = (e: PointerEvent) => { if (e.pointerId === dragId) dragId = -1; };
107	  canvas.addEventListener('pointerup', end);
108	  canvas.addEventListener('pointercancel', end);
109	  canvas.addEventListener('lostpointercapture', end);
110	}
