26	// Dù chính đứng yên ở BASE, hướng +X; bot bay tại chỗ phía trước, hơi lệch hai bên
27	const BASE = { x: 500, y: 150, z: 100 };
28	function bot(name, ox, oz) {
29	  const ws = new WebSocket(`ws://${HOST}/sky`, { headers: { Origin: 'http://127.0.0.1' } });
30	  const b = { ws, timer: null };
31	  ws.onopen = () => ws.send(JSON.stringify({ t: 'join', name }));
32	  ws.onmessage = (e) => {
33	    if (JSON.parse(e.data).t === 'joined' && !b.timer) b.timer = setInterval(() => ws.send(JSON.stringify({ t: 'pos', x: BASE.x + ox, y: BASE.y + 5, z: BASE.z + oz, yaw: 0, bank: 0 })), 200);
34	  };
35	  b.close = () => { clearInterval(b.timer); try { ws.close(); } catch { /* bỏ qua */ } };
36	  return b;
37	}
38	// Bot bay thẳng theo +X với vận tốc v (m/s), gửi ts = giờ của bot như khách thật
39	function lineBot(name, v, oz) {
40	  const ws = new WebSocket(`ws://${HOST}/sky`, { headers: { Origin: 'http://127.0.0.1' } });
41	  const b = { ws, timer: null }, t0 = Date.now();
42	  ws.onopen = () => ws.send(JSON.stringify({ t: 'join', name }));
43	  ws.onmessage = (e) => {
44	    if (JSON.parse(e.data).t === 'joined' && !b.timer) b.timer = setInterval(() => { const ts = Date.now(); ws.send(JSON.stringify({ t: 'pos', x: Math.round((BASE.x + 60 + v * (ts - t0) / 1000) * 10) / 10, y: BASE.y + 5, z: BASE.z + oz, yaw: 0, bank: 0, ts })); }, 200);
