454	  // 5d: bấm phím lúc đếm ngược giữ slot; 5e: nhịp sống không nhân đôi sau khi vào bay lại
455	  await I.page.waitForFunction(() => document.getElementById('exMpIdle').getClientRects().length > 0, null, { timeout: 8000 }).catch(() => {});
456	  const shown2 = await idleVis(I.page);
457	  await I.page.keyboard.press('a');
458	  await frames(I.page, 3);
459	  const hidAfterKey = !(await idleVis(I.page));
460	  const hb0 = await I.page.evaluate(() => window.__hb);
461	  let still = true;
462	  for (let i = 0; i < 24; i++) { await I.page.keyboard.press(i % 2 ? 'w' : 'ArrowLeft'); await sleep(400); if (obs.n !== 1) still = false; }
463	  const live2 = await I.page.evaluate(() => ({ phase: window.__app.multi.session.phase, hb: window.__hb }));
464	  const hbN = live2.hb - hb0;
465	  check(`Bấm phím lúc đếm ngược: đếm ngược ẩn, giữ slot qua ${((Date.now() - t0) / 1000).toFixed(0)} s (quá hạn 3 s nhiều lần), lobby vẫn 1 người`, shown2 && hidAfterKey && live2.phase === 'flying' && still);
466	  check(`Vào bay lại từ lời mời: nhịp sống không nhân đôi (${hbN} hb trong ~9,6 s, chu kỳ 3 s => 2 đến 4)`, hbN >= 2 && hbN <= 4);
467	  check('Lỗi console của trang rời máy = 0', I.errors.length === 0);
468	  if (I.errors.length) console.log(I.errors.join('\n'));
469	  await I.page.close();
470	  await lobbyIs(0, 6000);
471	
472	  // 5f: đóng trang đang bay: bot thấy lobby giảm trong 3 s
473	  const C = await openApp(browser, URLI);
474	  await C.page.evaluate(() => window.__app.multi.fly('Closer'));
475	  await C.page.waitForFunction(() => window.__app.explore.active() && window.__app.multi.session.phase === 'flying', null, { timeout: 60000 });
476	  const sawOne = await lobbyIs(1, 5000);
477	  await C.page.close();
478	  check('Đóng trang đang bay: ws quan sát thấy lobby giảm về 0 trong 3 s', sawOne && await lobbyIs(0, 3000));
479	
480	  // 5g: tab ẩn + rAF dừng 23 s (lâu hơn slotTimeoutMs 10 s + một chu kỳ quét 10 s): chỉ nhịp sống giữ slot; quay lại không lỗi
481	  const H = await openApp(browser, URLI);
482	  await H.page.evaluate(() => window.__app.multi.fly('Hidden'));
483	  await H.page.waitForFunction(() => window.__app.explore.active() && window.__app.multi.session.phase === 'flying', null, { timeout: 60000 });
484	  await lobbyIs(1, 5000);
485	  await H.page.evaluate(() => {
486	    const raf = window.requestAnimationFrame.bind(window); window.__raf = raf; window.__held = [];
487	    window.requestAnimationFrame = (cb) => { window.__held.push(cb); return 0; };
488	    Object.defineProperty(document, 'hidden', { configurable: true, get: () => true });
489	    Object.defineProperty(document, 'visibilityState', { configurable: true, get: () => 'hidden' });
490	    document.dispatchEvent(new Event('visibilitychange'));
491	  });
492	  await sleep(23000);
493	  const keptHidden = obs.n === 1;
494	  const phaseHidden = await H.page.evaluate(() => window.__app.multi.session.phase);
495	  await H.page.evaluate(() => {
496	    delete document.hidden; delete document.visibilityState;
497	    document.dispatchEvent(new Event('visibilitychange'));
498	    window.requestAnimationFrame = window.__raf; const h = window.__held.splice(0); h.forEach((cb) => window.__raf(cb));
499	  });
500	  await frames(H.page, 20);
501	  const back = await H.page.evaluate(() => ({ phase: window.__app.multi.session.phase, active: window.__app.explore.active() }));
502	  check(`Tab ẩn và rAF dừng 23 s: slot còn (lobby ${obs.n}, phase ${phaseHidden}); quay lại vẫn bay, console không lỗi`, keptHidden && phaseHidden === 'flying' && back.phase === 'flying' && back.active && H.errors.length === 0);
503	  if (H.errors.length) console.log(H.errors.join('\n'));
504	  await H.page.close();
505	  try { ows.close(); } catch { /* bỏ qua */ }
506	
507	  live.splice(0).forEach((b) => b.close());
508	} catch (e) {
509	  check('ngoại lệ: ' + e.message, false);
510	} finally {
511	  bots.forEach((b) => b.close());
512	  try { await browser?.close(); } catch { /* bỏ qua */ }
513	  try { srv?.close(); } catch { /* bỏ qua */ }
514	  stop();
515	  await sleep(1500);
516	}
517	console.log(problems.length ? `multi-check: LỖI (${problems.length}): ${problems.join('; ')}` : 'multi-check: đạt');
518	process.exit(problems.length ? 1 : 0);
