86	  }
87	
88	  // Mục 2 — cao độ tại 12 điểm mẫu
89	  {
90	    const r = await P.evaluate(() => {
91	      const S = window.__app.stroll, SHZ = -1080;
92	      const pts = [
93	        ['Cầu Rồng lề Nam', -240, 17.4], ['Cầu Rồng lề Bắc', 150, -17.6], ['Cầu Rồng lòng đường gần đầu Tây', -300, 9], ['Cầu Rồng đường dẫn Đông (vỉa hè)', 345, 18.2],
94	        ['Cầu sông Hàn lề Nam phần cố định', -150, SHZ + 5.5], ['Cầu sông Hàn lề Bắc nhịp quay', 40, SHZ - 5.5], ['Cầu sông Hàn lòng đường', 200, SHZ + 3], ['Cầu sông Hàn đường dẫn Đông', 300, SHZ + 2.5],
