103	      p.ok && !!p.hit && Math.abs(p.y - p.hit.y) <= 0.15);
104	  }
105	
106	  // Mục 3 + 4 — 20 000 bước ngẫu nhiên, oracle bằng tam giác thật của lưới rắn
107	  {
108	    const r = await P.evaluate(() => {
109	      const a = window.__app, S = a.stroll, T = a.THREE, C = S.CONFIG_stroll, map = S.stroll.map, B = C.bounds, R = C.radius;
110	      const Ray = new T.Raycaster().ray.constructor;
111	      /* --- gom tam giác thế giới của các lưới rắn vào lưới ô 2 m --- */
112	      const CELL = 2, cells = new Map(), tri = [];
113	      const key = (ix, iz) => ix * 100003 + iz;
114	      const v = [new T.Vector3(), new T.Vector3(), new T.Vector3()], mw = new T.Matrix4(), mi = new T.Matrix4(), p = new T.Vector3(), q = new T.Quaternion(), sc = new T.Vector3();
115	      const boxes = [];   // hộp bao thế giới của từng nhà (cho mục 5)
116	      const counts = {};
117	      const addGeo = (geo, m, tag, box) => {
118	        const pos = geo.attributes.position, idx = geo.index, n = idx ? idx.count : pos.count;
119	        for (let i = 0; i + 2 < n; i += 3) {
120	          for (let k = 0; k < 3; k++) v[k].fromBufferAttribute(pos, idx ? idx.getX(i + k) : i + k).applyMatrix4(m);
121	          const x0 = Math.min(v[0].x, v[1].x, v[2].x), x1 = Math.max(v[0].x, v[1].x, v[2].x), z0 = Math.min(v[0].z, v[1].z, v[2].z), z1 = Math.max(v[0].z, v[1].z, v[2].z);
122	          if (box) { box.x0 = Math.min(box.x0, x0); box.x1 = Math.max(box.x1, x1); box.z0 = Math.min(box.z0, z0); box.z1 = Math.max(box.z1, z1); }
123	          if (x1 < B.x0 - 5 || x0 > B.x1 + 5 || z1 < B.z0 - 5 || z0 > B.z1 + 5) continue;
124	          const t = tri.length; tri.push([v[0].clone(), v[1].clone(), v[2].clone(), tag]);
125	          for (let ix = Math.floor(x0 / CELL); ix <= Math.floor(x1 / CELL); ix++) for (let iz = Math.floor(z0 / CELL); iz <= Math.floor(z1 / CELL); iz++) {
126	            const k = key(ix, iz); let l = cells.get(k); if (!l) { l = []; cells.set(k, l); } l.push(t);
127	          }
128	          counts[tag] = (counts[tag] || 0) + 1;
129	        }
130	      };
131	      const addObj = (root, tag) => {
132	        root.updateMatrixWorld(true);
133	        root.traverse((o) => {
134	          if (!o.isMesh) return;
135	          if (o.isInstancedMesh) { for (let i = 0; i < o.count; i++) { o.getMatrixAt(i, mi); mi.decompose(p, q, sc); if (sc.x < 1e-6) continue; addGeo(o.geometry, mw.multiplyMatrices(o.matrixWorld, mi), tag); } }
136	          else addGeo(o.geometry, o.matrixWorld, tag);
137	        });
138	      };
139	      a.scene.updateMatrixWorld(true);
140	      /* nhà: InstancedMesh level gần của THREE.LOD (như collectBuildings) */
141	      a.scene.traverse((o) => {
142	        if (!o.isInstancedMesh || !o.parent || !o.parent.isLOD || o.parent.levels[0]?.object !== o) return;
143	        for (let i = 0; i < o.count; i++) {
144	          o.getMatrixAt(i, mi); mi.decompose(p, q, sc); if (sc.x < 1e-6) continue;
145	          mw.multiplyMatrices(o.matrixWorld, mi); p.set(0, 0, 0).applyMatrix4(mw);
146	          if (p.x < B.x0 - 60 || p.x > B.x1 + 60 || p.z < B.z0 - 60 || p.z > B.z1 + 60) continue;
147	          const box = { x0: Infinity, x1: -Infinity, z0: Infinity, z1: -Infinity }; addGeo(o.geometry, mw, 'nhà', box); boxes.push(box);
148	        }
149	      });
150	      const named = {};
151	      for (const n of ['dragon-body', 'dragon-head', 'sh-tower', 'rf-landmarks']) { const o = a.scene.getObjectByName(n); named[n] = !!o; if (o) addObj(o, n); }
152	      /* --- 24 tia ngang dài R quanh (x, z) ở 3 cao độ trên mặt đứng --- */
153	      const ray = new Ray(), tgt = new T.Vector3(), seen = new Set();
154	      const DIRS = Array.from({ length: 8 }, (_, i) => [Math.cos(i * Math.PI / 4), Math.sin(i * Math.PI / 4)]);
155	      const gather = (x, z, L) => {
156	        seen.clear();
157	        for (let ix = Math.floor((x - L) / CELL); ix <= Math.floor((x + L) / CELL); ix++) for (let iz = Math.floor((z - L) / CELL); iz <= Math.floor((z + L) / CELL); iz++) {
158	          const l = cells.get(key(ix, iz)); if (l) for (const t of l) seen.add(t);
159	        }
160	      };
161	      const probe = (x, g, z) => {
162	        gather(x, z, R); const hits = [];
163	        if (!seen.size) return hits;
164	        for (const dh of [0.3, 1.0, 1.7]) for (const [dx, dz] of DIRS) {
165	          ray.origin.set(x, g + dh, z); ray.direction.set(dx, 0, dz);
166	          for (const t of seen) {
167	            const h = tri[t], hp = ray.intersectTriangle(h[0], h[1], h[2], false, tgt);
168	            if (hp && hp.distanceTo(ray.origin) <= R) { hits.push({ tag: h[3], dh, d: +hp.distanceTo(ray.origin).toFixed(4) }); break; }
169	          }
170	        }
171	        return hits;
172	      };
173	      /* một tia ngang dài len từ (x, y, z) theo (dx, dz): khoảng cách tới tam giác gần nhất, hoặc null */
174	      const castH = (x, y, z, dx, dz, len) => {
175	        gather(x, z, len); let best = null;
176	        ray.origin.set(x, y, z); ray.direction.set(dx, 0, dz);
177	        for (const t of seen) {
178	          const h = tri[t], hp = ray.intersectTriangle(h[0], h[1], h[2], false, tgt);
179	          if (hp) { const d = hp.distanceTo(ray.origin); if (d <= len && (best === null || d < best)) best = d; }
180	        }
181	        return best;
182	      };
183	      /* khoảng cách mặt bằng từ (x, z) tới hộp nhà (0 nếu ở trong); trong hộp (đã thu 1 cm) = nhân vật nằm trong khối nhà */
184	      const EPS = 0.01;
185	      const boxDist = (b, x, z) => Math.hypot(Math.max(b.x0 - x, 0, x - b.x1), Math.max(b.z0 - z, 0, z - b.z1));
