255:.ex-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;}
256:.ex-card{display:flex;flex-direction:column;align-items:flex-start;gap:4px;min-height:84px;padding:12px 14px;text-align:start;}
257:.ex-card b{font-weight:600;font-size:14px;color:var(--text);}
258:.ex-card span,.ex-card i{font-style:normal;font-size:11.5px;line-height:1.4;color:var(--muted);}
259:.ex-card:disabled{opacity:.55;cursor:not-allowed;}
260:.ex-card:disabled .ex-note{color:var(--gold);}
261:.ex-card:focus-visible{outline:2px solid var(--gold);outline-offset:2px;}
263:.ex-cards[hidden],.ex-mp-lobby [hidden],.ex-mp-lobby[hidden]{display:none;}
264:.ex-mp-lobby{display:flex;flex-direction:column;gap:10px;min-width:min(340px,100%);}
265:.ex-mp-lobby h2{margin:0;}
266:.ex-mp-seatline{display:flex;align-items:center;gap:10px;font-size:13px;color:var(--text);}
271:#exMpList .ex-mp-row{padding:4px 0;border-bottom:1px solid rgba(255,255,255,.08);overflow-wrap:anywhere;}
272:#exMpList .ex-mp-row i{width:9px;height:9px;border-radius:50%;flex:none;}
273:.ex-mp-field{display:flex;flex-direction:column;gap:4px;font-size:12px;color:var(--muted);}
274:.ex-mp-field input{font:500 14px/1.2 var(--font-body);color:var(--text);background:rgba(0,0,0,.35);border:1px solid var(--gold);border-radius:4px;padding:8px 10px;box-sizing:border-box;width:100%;}
275:.ex-mp-field input:focus-visible{outline:2px solid var(--gold);outline-offset:1px;}
278:.ex-mp-btn{width:100%;padding:10px;font-weight:700;font-size:13px;color:#14191c;background:var(--gold);border-color:var(--gold);}
279:.ex-mp-btn:hover:not(:disabled){background:var(--gold);}
280:.ex-mp-btn:disabled{opacity:.45;cursor:not-allowed;}
281:.ex-mp-btn:focus-visible{outline:2px solid #fff;outline-offset:2px;}
282:.ex-mp-btn.ex-mp-alt{color:var(--text);background:transparent;border-color:var(--gold);font-weight:600;}   /* nút phụ: Quay lại, Bay một mình khi có máy chủ */
283:.ex-mp-btn.ex-mp-alt:hover:not(:disabled){background:rgba(255,255,255,.08);}
290:.ex-mp-label{position:absolute;left:0;top:0;padding:2px 7px;font:500 11px/1.2 var(--font-body);color:var(--text);background:rgba(10,18,30,.72);border-radius:4px;white-space:nowrap;will-change:transform;direction:ltr;}
291:.ex-mp-label[hidden]{display:none;}
293:.ex-mp-head{font-weight:600;margin-bottom:2px;}
294:.ex-mp-row{display:flex;align-items:center;gap:6px;}
295:.ex-mp-row.me{font-weight:600;}
296:.ex-mp-row i{width:9px;height:9px;border-radius:50%;flex:none;}
299:body.ex-watching #exHint,body.ex-watching #exSpeed{display:none;}
303:body.ex-watching #exMpWatch:not([hidden]){display:block;position:fixed;left:50%;transform:translateX(-50%);top:calc(14px + env(safe-area-inset-top,0px));padding:8px 14px;font-size:13px;color:var(--text);max-width:calc(100vw - 32px);box-sizing:border-box;text-align:center;pointer-events:none;z-index:5;}
304:body.ex-watching #exMpInvite:not([hidden]){display:flex;align-items:center;gap:10px;flex-wrap:wrap;justify-content:center;position:fixed;left:50%;transform:translateX(-50%);bottom:calc(14px + env(safe-area-inset-bottom,0px));padding:10px 14px;font-size:13px;color:var(--text);max-width:calc(100vw - 32px);box-sizing:border-box;z-index:6;}
307:#exMpInvite .ex-mp-btn{width:auto;padding:8px 16px;}
308:.ex-mp-note{margin:0 0 12px;font-size:12.5px;line-height:1.45;color:var(--gold);}
309:.ex-mp-note[hidden]{display:none;}
314:body.explore.stroll #exHint,body.explore.stroll #exSpeed{display:none;}
315:body.stroll #scene{cursor:grab;}
316:body.stroll #scene:active{cursor:grabbing;}

