// Gỡ lỗi: roster ở Mục 1 multi-check. Chạy từ thư mục repo: node <file>
import { spawn } from 'node:child_process';
import { pathToFileURL } from 'node:url';
const repo = 'D:/2026 - Tuan/danang-vite/';
const { serveDir, launch, openApp, frames } = await import(pathToFileURL(repo + 'tests/lib.mjs').href);
const PORT = 8797, HOST = `127.0.0.1:${PORT}`;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const wr = spawn('npx.cmd', ['wrangler', 'dev', '--port', String(PORT)], { cwd: repo + 'server/multi/', shell: true, stdio: ['ignore', 'pipe', 'pipe'] });
let log = ''; wr.stdout.on('data', (d) => { log += d; }); wr.stderr.on('data', (d) => { log += d; });
const stop = () => { try { spawn('taskkill', ['/pid', String(wr.pid), '/T', '/F']); } catch { } };
const bots = [];
function bot(name) {
  const ws = new WebSocket(`ws://${HOST}/sky`, { headers: { Origin: 'http://127.0.0.1' } });
  let tm = null;
  ws.onopen = () => ws.send(JSON.stringify({ t: 'join', name }));
  ws.onmessage = (e) => { if (JSON.parse(e.data).t === 'joined' && !tm) tm = setInterval(() => ws.send(JSON.stringify({ t: 'pos', x: 600, y: 155, z: 100, yaw: 0, bank: 0 })), 200); };
  bots.push(() => { clearInterval(tm); ws.close(); });
}
let browser, srv;
try {
  for (let i = 0; i < 120 && !/Ready on/.test(log); i++) await sleep(500);
  srv = await serveDir(repo + 'dist/');
  browser = await launch();
  const P = await openApp(browser, srv.url + '?multi=' + encodeURIComponent(`ws://${HOST}/sky`));
  await P.page.evaluate(() => window.__app.multi.fly('Tester'));
  await P.page.waitForFunction(() => window.__app.explore.active() && window.__app.multi.session.phase === 'flying', null, { timeout: 60000 });
  const r0 = await P.page.evaluate(() => ({ html: document.getElementById('exMpRoster').outerHTML, it: document.getElementById('exMpRoster').innerText }));
  console.log('R0', JSON.stringify(r0));
  ['Ann', 'Binh', 'Chi', 'Dung'].forEach(bot);
  await sleep(4000); await frames(P.page, 5);
  const r1 = await P.page.evaluate(() => ({ html: document.getElementById('exMpRoster').outerHTML, it: document.getElementById('exMpRoster').innerText, fl: window.__app.multi.session.flyers, wk: window.__app.multi.session.walkers }));
  console.log('R1', JSON.stringify(r1));
  console.log('errors', P.errors);
} catch (e) { console.log('EXC', e); }
finally { bots.forEach((f) => f()); await browser?.close(); srv?.close(); stop(); await sleep(1500); process.exit(0); }

